parameters.jsCode:
// ===========================================================================
//  RUN SETTINGS — the only node you normally touch.
// ===========================================================================

// Which outreach_log campaign this send belongs to, and which contact source
// list to draw from. Keeping both equal to the list's tag puts every touch
// to that list on one timeline.
const CAMPAIGN = 'example_list';
const SOURCE   = 'example_list';

// true = only companies whose `sources` holds SOURCE and nothing else. A firm
// that also came in through another list is skipped — those lists carry
// their own campaign history.
const ONLY_THIS_SOURCE = true;

// Which row of the `offers` table to send, and the week shown in the subject
// line and the opening sentence. Bump OFFER_ID for every new offer: it is
// what stops the same offer reaching a company twice.
const OFFER_ID = 'offer_001';
const WEEK     = '38';        // '38' or '38-39'

// 'new'    = companies with no outreach_log row at all — never touched by
//            anyone, in any campaign. The first send to a fresh list.
// 'repeat' = companies already touched in THIS campaign, for a later offer.
const MODE = 'new';

// repeat mode only: how many days must have passed since that company's last
// touch in this campaign. 1 = not today. Stops a second offer landing hours
// after the first when a batch went out the same day.
const MIN_DAYS_SINCE_LAST = 1;

// Goes into outreach_log.products — what this offer actually covered.
const PRODUCTS = 'human consumption';

// How many companies this run mails. One address per company; the batch is
// split evenly between sender A and sender B.
const BATCH = 175;

// ===========================================================================

// These are interpolated into SQL by string substitution, so keep them to
// safe characters. A typo stops the run here rather than building a strange
// query.
const SAFE = /^[A-Za-z0-9_()-]+$/;
if (!SAFE.test(CAMPAIGN)) throw new Error('CAMPAIGN: letters, digits, _ ( ) - only');
if (!SAFE.test(SOURCE))   throw new Error('SOURCE: letters, digits, _ ( ) - only');
if (!SAFE.test(OFFER_ID)) throw new Error('OFFER_ID: letters, digits, _ ( ) - only');
if (!['new', 'repeat'].includes(MODE)) throw new Error("MODE must be 'new' or 'repeat'");
if (!/^\d{1,2}(-\d{1,2})?$/.test(String(WEEK))) throw new Error("WEEK must look like '38' or '38-39'");
if (!Number.isInteger(MIN_DAYS_SINCE_LAST) || MIN_DAYS_SINCE_LAST < 0 || MIN_DAYS_SINCE_LAST > 365)
  throw new Error('MIN_DAYS_SINCE_LAST must be 0-365');
if (!Number.isInteger(BATCH) || BATCH < 1 || BATCH > 500) throw new Error('BATCH must be 1-500');

return [{ json: {
  campaign: CAMPAIGN,
  source: SOURCE,
  only_this_source: ONLY_THIS_SOURCE,
  offer_id: OFFER_ID,
  week: String(WEEK),
  mode: MODE,
  min_days: MIN_DAYS_SINCE_LAST,
  products: PRODUCTS,
  batch: BATCH,
} }];

parameters.query:
-- Every stored offer. Build email picks the one whose offer_id matches
-- Run settings and lists the rest in its error message if it is missing.
select offer_id, offer from offers order by created_at;

parameters.jsCode:
// Builds one email. The offer text itself lives in the `offers` table —
// edit it there, not here.
//
// The sender was already decided in "Select companies" (an even A / B split
// over the batch), so all this node does with it is choose the matching
// signature. Greeting, subject, body and signature therefore always belong to
// the same person.

const cfg  = $('Run settings').first().json;
const rows = $('Get offers').all();

const row = rows.find(r => String(r.json.offer_id) === String(cfg.offer_id));
if (!row) {
  throw new Error(
    `No row with offer_id="${cfg.offer_id}" in the offers table. ` +
    `Available: ${rows.map(r => r.json.offer_id).filter(Boolean).join(', ') || '(table is empty)'}`
  );
}

// The stored offer keeps its own layout — an HTML table, or a block wrapped in
// white-space: pre-wrap. Only the newlines need turning into <br>.
const offerHtml = String(row.json.offer).replace(/\n/g, '<br>');

// One signature per sending mailbox. Replace the placeholders with the real
// name, phone, address and company of each sender.
const SIGNATURES = {
  A: `
<div style="font-family: Arial, sans-serif; color: #222; line-height: 1.2;">
    <p style="margin-bottom: 15px; font-size: 16px;">Best regards, Sender A</p>
    <div style="font-size: 14px;">
        <strong>Mob.:</strong> +00 000 000 000<br>
        <strong>e-mail:</strong> sender-a@example.com<br>
        <strong>Web:</strong> www.example.com
    </div>
    <hr style="border: 0; border-top: 1px solid #eee; margin: 15px 0;">
    <p style="font-size: 11px; color: #999; margin-top: 10px;">
        <i>If you’d rather not receive any more offers, please let me know with a quick <span style="color: #1155cc;">"Unsubscribe"</span> reply.</i>
    </p>
</div>`,
  B: `
<div style="font-family: Arial, sans-serif; color: #222; line-height: 1.2;">
    <p style="margin-bottom: 15px; font-size: 16px;">Best regards, Sender B</p>
    <div style="font-size: 14px;">
        <strong>Mob.:</strong> +00 000 000 000<br>
        <strong>e-mail:</strong> sender-b@example.com<br>
        <strong>Web:</strong> www.example.com
    </div>
    <hr style="border: 0; border-top: 1px solid #eee; margin: 15px 0;">
    <p style="font-size: 11px; color: #999; margin-top: 10px;">
        <i>If you’d rather not receive any more offers, please let me know with a quick <span style="color: #1155cc;">"Unsubscribe"</span> reply.</i>
    </p>
</div>`,
};

const out = [];

for (const item of $input.all()) {
  const d = item.json;

  const who = String(d.who || '').trim();
  // The Switch after this node routes on `who`. An unexpected value there
  // would fall out of every branch and the item would vanish without a send
  // and without a log row — stop instead.
  if (!SIGNATURES[who]) {
    throw new Error(`Row for ${d.company_key} has who="${d.who}"; expected 'A' or 'B'`);
  }

  // company_name is filled for every row the query returns, but never greet
  // anyone as "undefined Team" if that ever changes.
  const name = String(d.company_name || '').trim();
  const greeting = name ? `Dear ${name} Team,` : 'Dear Sir or Madam,';
  const subject  = name
    ? `Frozen meat and offal – Week ${cfg.week} – ${name}`
    : `Frozen meat and offal – Week ${cfg.week}`;

  const body =
    `${greeting}<br><br>` +
    `Please find below our available meat and offal offer for week ${cfg.week}.<br><br>` +
    `${offerHtml}<br><br>` +
    `Should you have any questions, or if you are interested in products not listed, feel free to reach out.<br><br>` +
    SIGNATURES[who];

  // Everything from the query is carried through so the logging nodes can read
  // it with $('Build email').first() — safe, the loop hands over one item.
  out.push({ json: { ...d, subject, body } });
}

return out;
